package com.joaosantos.workout.dto;

import java.util.List;

/**
 * Immutable Java Record representing the top-level structured output
 * schema generated by Spring AI and Google Gemini.
 *
 * @param title           concise title of the synthesized training session
 * @param focusArea       targeted muscle group or training split (e.g., "Hypertrophy Push Session")
 * @param warmupRoutine   dynamic mobility and warm-up routine tailored to this specific session
 * @param cooldownRoutine dynamic cool-down and muscle relaxation routine tailored to this session
 * @param explanation     biomechanical justification, warm-up advice, and volume rationale
 * @param exercises       ordered list of synthesized exercise routines
 */
public record WorkoutPlanRecord(
        String title,
        String focusArea,
        String warmupRoutine,
        String cooldownRoutine,
        String explanation,
        List<ExerciseRecord> exercises
) {
}
